mapper.select:
SELECT
    np.id AS productId,
    np.name AS productName,
    if(nb.is_deleted = 0, nb.id, null) AS brandId,
    if(nb.is_deleted = 0, nb.name, null) AS brandName,
    if(nc.is_deleted = 0, nc.id, null) AS categoryId,
    if(nc.is_deleted = 0, nc.name, null) AS categoryName,
    np.create_time AS createTime
FROM newbie_product np
LEFT JOIN newbie_brand nb ON np.brand_id = nb.id
LEFT JOIN newbie_category nc ON np.category_id = nc.id
WHERE np.is_deleted = 0
ORDER BY np.name asc;
